style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.imgur.com/8RnSP9Z.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make main page containers semi-transparent */
  .container-main, .content, .navbar, .rbx-header, .section-content, .game-page {
    background-color: rgba(255, 255, 255, 0.5) !important; /* More transparent */
    backdrop-filter: blur(5px);
  }

  .navbar {
    background-color: rgba(255, 105, 180, 0.8) !important;
    border-bottom: 2px solid #ff69b4 !important;
  }

  a, .text-label {
    color: #ff69b4 !important;
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
  }
}
